head.script:
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        window.evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
	if(WebSquare.wUnit.getDomById(id) === null)
		window.el = WebSquare.wUnit.getDomById('widgetContainer1_widget0_content_wq_uuid_11_tooltip');
	else
		window.el = WebSquare.wUnit.getDomById(id);

    scwin.fireOver(el);
}
scwin.getTooltip = function() {	
    return WebSquare.wUnit.getDomById($p.id + "widgetContainer1_widget0_content_wq_uuid_19_tooltip").innerText == "(0, 2)[20020922]";
}

scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('widgetContainer1_widget0_title_btnMaximize').click()");
    WebSquare.wUnit.addCommand("pause", "1500");	
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('widgetContainer1_widget0_content_wq_uuid_19_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 1. row, col, label 값이 tooltipFormatter를 통해 정상적으로 보여진다.(이전에는 label 값만 보여짐)
    //The row, col, and label values are normally displayed through the tooltipFormatter.(Previously only the label value is shown)
    WebSquare.wUnit.addCommand("assert", "scwin.getTooltip()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

